const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas(500, 500);
  p5obj.colorMode(p5obj.RGB);
  p5obj.noStroke();
  p5obj.frameRate(30);
}

p5obj.draw = () => 
{

  p5obj.background(255, 120, 100);
  let d: number = p5obj.second();
  let m: number = p5obj.minute();
  let y: number = p5obj.hour();


  //蜊亥ｾ・
  p5obj.fill(53, 62, 87);
  p5obj.rect(0, 250, 500, 250);


  //遘抵ｼ夐ｳ･・育判髱｢繧呈ｨｪ縺ｫ縺ｫ60蛻・牡・・
  p5obj.fill(53, 62, 87);
  p5obj.ellipse(d*8.3-50, 50, 80, 80);
  p5obj.ellipse(d*8.3, 50, 25, 5);
  p5obj.ellipse(d*8.3-12, 50, 30, 20);
  p5obj.fill(255, 120, 100);
  p5obj.ellipse(d*8.3-80, 50, 80, 80);
  p5obj.fill(53, 62, 87);
  p5obj.ellipse(d*8.3-40, 50, 50, 20);
  p5obj.fill(255, 120, 100);
  p5obj.ellipse(d*8.3-60, 50, 25, 5);


  //譎る俣・壼､ｪ髯ｽ・育判髱｢繧堤ｸｦ縺ｫ・抵ｼ泌・蜑ｲ縲∝壕蜑榊壕蠕後〒濶ｲ縺悟､峨ｏ繧具ｼ・
  if (y*20>250)
  {
    p5obj.fill(255, 120, 100);
  }
  else
  {
    p5obj.fill(53, 62, 87);
  }
  p5obj.ellipse(250, y*20.8, 80, 80);


  //蛻・ｼ壹Κ繝・ヨ・育判髱｢繧呈ｨｪ縺ｫ縺ｫ60蛻・牡・・
  p5obj.fill(53, 62, 87);
  p5obj.triangle(m*8.3-40, 235, m*8.3, 235, m*8.3, 150);
  p5obj.triangle(m*8.3+5, 235, m*8.3+35, 235, m*8.3+5, 160);
  p5obj.triangle(m*8.3-45, 240, m*8.3, 270, m*8.3+40, 240);
}

};

export default sketch;
