const sketch = (p5obj:any) => {
// 潮位タイマー
let fOceanHeight: number = 0;
let fOceanTimer: number = 0;

// === Time Handling ===

let hourCurrent: number = 0;
       // 現在の時（0~23）
let minuteCurrent: number = 0;
     // 現在の分（0~59）
let secondCurrent: number = 0;
     // 現在の秒（0~59）
let deltaTime: number = 0;
       // 前フレームからの経過時間（秒,0~1）
let deltaTimePerSec: number = 0;
 // 前回の秒が切り替わってからの経過時間（秒,0~1）
let isHourAnim: number = 0;    // アニメーションフラグ（1:アニメーション中）
let isMinuteAnim: number = 0;
let isSecondAnim: number = 0;


p5obj.setup = () => 
{
  p5obj.createCanvas( 400, 400 );
  p5obj.frameRate( 30 );  // フレームレートの指定

  // === Time Init ===
  initTime();
}

p5obj.draw = () => 
{
  // === Time Update ===
  updateTimePre();

  //hourCurrent = 1;  // 時 を指定して描画を確認したい場合に一時的に有効化

  // === 画面のクリア ===

  // 画面をクリア
  p5obj.fill( 204  );
  p5obj.noStroke();
  p5obj.rect( 0, 0, p5obj.width, p5obj.height );

  // 既定の描画カラーに戻す．
  p5obj.fill( 255 );
  p5obj.stroke( 0 );

  // === アニメーションを記述 ===
  
  // 現在の時を調整 6~29
  //let fHourOffset6: number = ( 2 * secondCurrent ) / 5 + 6;  // 秒でテスト
  let fHourOffset6: number = hourCurrent + 6;
  // 24以降を巻き戻す 0~23
  // 0~12が夜,13~23が昼
  let fHourShisted: number = fHourOffset6 % 24;

  // 太陽と月の回転角度 0~90°
  let fSunMoonRot: number = 90 * ( fHourShisted % 12 ) / 12.0;

  // 月or太陽，空の描画
  p5obj.colorMode(p5obj.HSB, 100 );
  p5obj.push();
  if ( fHourShisted < 12 )
  {
    // 夜の進行0~1
    let fProgress: number = fHourShisted / 11.0;
    let fProgressSin: number = p5obj.sin( p5obj.radians( 180 * fProgress ) );

    // 空
    p5obj.fill( fProgress * 40  );
    p5obj.noStroke();
    p5obj.rect( 0, 0, p5obj.width, p5obj.height );

    // 月
    p5obj.translate( 200, 400 );
    p5obj.rotate( p5obj.radians( fSunMoonRot ) );
    let fBrightness: number = 60 + 40 * p5obj.sin( p5obj.radians( 180 * deltaTimePerSec ) );
    p5obj.fill( 15, 100, fBrightness );
    p5obj.circle( -240, -180, 100 );
    p5obj.fill( fProgress * 40 );
    // 月の影
    p5obj.ellipse( -245 - 100 * fProgressSin, -180 + 10 * fProgressSin, 100, 100 );
  }
  else
  {
    // 昼の進行0~1
    let fProgress: number = ( fHourShisted - 12 ) / 11.0;

    // 空
    p5obj.fill( 50 + 20 * fProgress, 20, 60 + 40 * p5obj.sin( p5obj.radians( 180 * fProgress ) ) );
    p5obj.noStroke();
    p5obj.rect( 0, 0, p5obj.width, p5obj.height );

    // 太陽
    p5obj.translate( 200, 380 );
    p5obj.rotate( p5obj.radians( fSunMoonRot ) );
    let fHue: number = 5 + 15 * p5obj.sin( p5obj.radians( 180 * deltaTimePerSec ) );
    p5obj.fill( fHue, 60, 80 );
    p5obj.circle( -240, -180, 100 );
  }
  p5obj.pop();

  // 海
  p5obj.colorMode(p5obj.HSB, 100 );
  p5obj.noStroke();
  p5obj.fill( p5obj.random( 60, 61 ), 60, 80, 40 );
  p5obj.ellipse( 200, 400, 400 + 2 * fOceanHeight, fOceanHeight );

  // 船
  p5obj.push();
  // 現在の秒と潮位の影響で位置を変える
  p5obj.translate( 20 + secondCurrent * 6, 400 - fOceanHeight / 2 );
  p5obj.colorMode(p5obj.HSB, 100 );
  p5obj.stroke( 0 );
  p5obj.fill( 0, 0, 100, 40 );
  p5obj.beginShape();
  p5obj.vertex( -30, -15 );
  p5obj.vertex( 25, -15 );
  p5obj.vertex( 15, 15 );
  p5obj.vertex( -25, 15 );
  p5obj.endShape(p5obj.CLOSE);
  p5obj.pop();

  // 秒が変化した時のアニメーション
  if ( secondCurrent != secondPrev )
  {
    isSecondAnim = 1;  // アニメーション開始

    // アニメーション初期化
  }
  if ( isSecondAnim == 1 )  // アニメーション中
  {
    // アニメーション中の処理を記述



    isSecondAnim = 0;  // アニメーション終了
  }


  // 分が変化した時のアニメーション
  if ( minuteCurrent != minutePrev )
  {
    isMinuteAnim = 1;  // アニメーション開始

    // アニメーション初期化
  }
  if ( isMinuteAnim == 1 )  // アニメーション中
  {
    isMinuteAnim = 0;  // アニメーション終了
  }

  // 時が変化した時のアニメーション
  // 潮位
  if ( hourCurrent != hourPrev )
  {
    isHourAnim = 1;  // アニメーションの開始

    // アニメーション初期化
    fOceanTimer = 0;  // タイマーリセット
  }
  if ( isHourAnim == 1 )
  {
    // 潮位が0に下がるアニメーション
    if ( fOceanTimer < 3 )
    {
      // ３秒間の間の進行率（0~1）
      let fOceanProgress: number = fOceanTimer / 3.0;

      // 潮位更新
      fOceanHeight = 40 + 360 * ( 1 - fOceanProgress );  // 400~40

      fOceanTimer += deltaTime;  // タイマー更新
    }
    else
    {
      isHourAnim = 0;  // アニメーション終了
    }
  }
  else
  {
    // 非アニメーション中
    // 分毎に海の潮位が上昇
    fOceanHeight = 40 + minuteCurrent * 6;  // 400~40
  }

  // 時間をデバッグ表示（ 提出前に非表示にすること．）
  /*
  p5obj.fill( 0 );
  p5obj.textSize(20);
  p5obj.text( hourCurrent + ":" + minuteCurrent + ":" + secondCurrent, 10, 20);
  p5obj.text( "deltaTimePerSec: " + deltaTimePerSec, 10, 40);
  p5obj.text( "deltaTime: " + deltaTime, 10, 60);
  */
  // === Time Update ===
  updateTimePost();
}

// === Time Handling ===
let hourPrev: number = 0;

let minutePrev: number = 0;

let secondPrev: number = 0;

let millisCurrent: number = 0;

let millisPrev: number = 0;

let millisPrevSec: number = 0;

// === Time Handling Functions===
const initTime = () => {
  hourCurrent = p5obj.hour();
  minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  hourPrev = p5obj.hour();
  minutePrev = p5obj.minute();
  secondPrev = p5obj.second();
  millisPrev = p5obj.millis();
  
  millisPrevSec = p5obj.millis();
}
const updateTimePre = () => { 
  if( hourPrev != p5obj.hour() ) hourCurrent = p5obj.hour();
  if( minutePrev != p5obj.minute() ) minuteCurrent = p5obj.minute();
  secondCurrent = p5obj.second();
  millisCurrent = p5obj.millis();
  
  deltaTime = ( millisCurrent - millisPrev ) / 1000;
  
  if ( secondCurrent != secondPrev )
  {
    millisPrevSec = p5obj.millis();
  }
  
  deltaTimePerSec = ( millisCurrent - millisPrevSec ) / 1000;
}
const updateTimePost = () => { 
  hourPrev = hourCurrent;
  minutePrev = minuteCurrent;
  secondPrev = secondCurrent;
  millisPrev = millisCurrent;
}
};

export default sketch;
