const sketch = (p5obj:any) => {
p5obj.setup = () => 
{
  p5obj.createCanvas( 1000, 1000 );
  p5obj.background(0);
  p5obj.blendMode(p5obj.SCREEN);
  dragonRoll(500,500);
  dragonRoll(500,-400);
  dragonRoll(500,1400);
  dragonRoll(-400,50);
  dragonRoll(-400,950);
  dragonRoll(1400,50);
  dragonRoll(1400,950);
  p5obj.save("sk_k4_23_A08.png");
}
const dragonRoll = (startX: number, startY: number) => {
  p5obj.push();
  p5obj.translate(startX,startY);
  for(let iR: number = 0; iR<360; iR+=90)
  {
  p5obj.push();
  p5obj.rotate(p5obj.radians(iR));
  p5obj.stroke(iR+p5obj.random(50),iR-p5obj.random(30),200);
  drawDragonCurve( 0, 0, 450, 450 );
  p5obj.pop();
  }
  p5obj.pop();
}
const drawDragonCurve = (fBeginX: number, fBeginY: number, fEndX: number, fEndY: number) => {
  // 開始点から終了点への距離
  let fLength: number = p5obj.sqrt( p5obj.pow( fEndX - fBeginX, 2 ) + p5obj.pow( fEndY - fBeginY, 2 ) );
  
  if( fLength > 10 )
  {
    // 直角三角形のX軸方向の大きさ
    let fTriangleX: number = ( fEndX - fBeginX ) / 2.0;
    
    // 直角三角形のY軸方向の大きさ
    let fTriangleY: number = ( fBeginY - fEndY ) /2.0;  // fBeginY方向へ向かうのが正
    
    let fBeginToNewX: number = fTriangleX + fTriangleY;
    let fEndToNewY: number = fTriangleX + fTriangleY;
    
    // 新たに生成される点のXY座標値
    let fNewX: number = fBeginX + fBeginToNewX;
    let fNewY: number = fEndY + fEndToNewY; 
    
    // 二つの線に再帰的に分割
    drawDragonCurve( fBeginX, fBeginY, fNewX, fNewY );
    drawDragonCurve( fEndX, fEndY, fNewX, fNewY );
  }
  else
  {
    p5obj.line( fBeginX, fBeginY, fEndX, fEndY );
  }
}

};

export default sketch;
