const sketch = (p5obj:any) => {
    p5obj.setup = () => {
p5obj.createCanvas(500, 500);
p5obj.background(30);
p5obj.stroke(240, 100);
p5obj.strokeWeight(0.1);
p5obj.noFill();
var r = 100;
var centx= p5obj.width/2;
var centy= p5obj.height/2;
var x, y;
var a, b, c, d, e, f;
var a2, b2, c2, d2, e2, f2;
var a3, b3, c3, d3, e3, f3;
for (var ang2 = 0; ang2 < 360; ang2 = ang2 + 360 / 12)
{
  for (var ang= 0; ang< 360; ang= ang+ 3)
  {
    var rad = p5obj.radians(ang); //隗貞ｺｦ繧偵Λ繧ｸ繧｢繝ｳ縺ｫ螟画鋤縺吶ｋ
    var rad2 = p5obj.radians(ang2);
    x = centx+ (r * p5obj.cos(rad))*1.3;
    y = centy+ (r * p5obj.sin(rad))*1.3;
    /*
    竊薙・蝗ｳ蠖｢繧貞・蠖｢縺ｫ蝗櫁ｻ｢縺輔○縺ｦ闃ｱ縺ｳ繧臥噪縺ｪ繧ゅ・繧剃ｽ懊ｋ
     p5obj.bezier(centx, p5obj.height*0.2, x-p5obj.cos(rad)*70, y-p5obj.sin(rad)*70-30, x-p5obj.cos(rad)*50, y-p5obj.sin(rad)*50-50, centx, centy);
     p5obj.bezier(centx, 0, x-p5obj.cos(rad)*50, y-p5obj.sin(rad)*50-60, x-p5obj.cos(rad)*20, y-p5obj.sin(rad)*20-80, centx, centy);
     p5obj.bezier(centx, p5obj.height*-0.5, x, y-110, x-p5obj.cos(rad)*-30, y-p5obj.sin(rad)*-30-130, centx, centy);
     */
    a3 = centx+ p5obj.height * p5obj.cos(rad2-45);
    b3 = centy+ p5obj.height * p5obj.sin(rad2-45);
    c3 = x + 110 * p5obj.cos(rad2);
    d3 = y + 110 * p5obj.sin(rad2);
    e3 = x -p5obj.cos(rad) * -30 + 130 * p5obj.cos(rad2);
    f3 = y -p5obj.sin(rad) * -30 + 130 * p5obj.sin(rad2);
    p5obj.bezier(a3, b3, c3, d3, e3, f3, centx, centy); //蝗ｳ蠖｢(螟ｧ)
    a2 = centx+ p5obj.height * 0.5 * p5obj.cos(rad2 + 11.25);
    b2 = centy+ p5obj.height * 0.5 * p5obj.sin(rad2 +11.25);
    c2 = x -p5obj.cos(rad) * 50 + 60 * p5obj.cos(rad2);
    d2 = y -p5obj.sin(rad) * 50 + 60 * p5obj.sin(rad2);
    e2 = x -p5obj.cos(rad) * 20 + 80 * p5obj.cos(rad2);
    f2 = y -p5obj.sin(rad) * 20 + 80 * p5obj.sin(rad2);
    p5obj.bezier(a2, b2, c2, d2, e2, f2, centx, centy);//蝗ｳ蠖｢(荳ｭ)
    a = centx+ p5obj.height * 0.3 * p5obj.cos(rad2);
    //蜈育ｫｯ縺御ｸｭ蠢・centx,centy)縺九ｉheight*0.3髮｢繧後※蝗櫁ｻ｢
    b = centy+ p5obj.height * 0.3 * p5obj.sin(rad2);
    c = x -p5obj.cos(rad) * 70 + 30 * p5obj.cos(rad2);
    d = y -p5obj.sin(rad) * 70 + 30 * p5obj.sin(rad2);
    e = x -p5obj.cos(rad) * 50 + 50 * p5obj.cos(rad2);
    f = y -p5obj.sin(rad) * 50 + 50 * p5obj.sin(rad2);
    p5obj.bezier(a, b, c, d, e, f, centx, centy); //蝗ｳ蠖｢(蟆・
  }
}

  };
};

export default sketch;
