const sketch = (p5obj:any) => {
/**

12進数時計

*/
let xsize: number = 1000;
let ysize: number = 500;
let center: number[] = new Array(2).fill([]);
let goal: number[] = new Array(2).fill([]);
let brickSize: number[] = new Array(2).fill([]);
let i: number = 0;
let k: number = 0;
let n: number;
let angle: number;
let x: number;
let y: number;
let r: number;
let circleCenter: number[] = [ xsize/5, xsize/2, xsize/5*4 ];
let circleRadius: number = 125;
let t: string;
let param: number;
let checked: boolean = false;
let divAmount: number[] = [ 12, 12 ];

let currentSec: number;
let formerSec: number = 0;
let second: number = 0;
let minute: number = 0;
let hour: number = 0;


p5obj.setup = () => 
{
  p5obj.createCanvas(1000, 500);
  p5obj.frameRate( 60 );
  p5obj.background(173, 157, 148);
  p5obj.colorMode(p5obj.RGB);

  //Defaultだと日本語が表示されないので...仕方なく...
  //const font = p5obj.loadFont("游明朝 Light");
  //const font = p5obj.loadFont("YUMINL.TTF");
  p5obj.textFont("游明朝 Light",50);

  //console.log(const .list());
}

//---------------------------------Main---------------------------------//
p5obj.draw = () =>  { //Refresh, 極座標系で行う
  //連続的な秒数を取得
  getTimes();

  //画面初期化
  p5obj.background(173, 157, 148);

  //背景の表示
  drawBackGround();

  //円の表示
  drawCircle(0);
  drawCircle(1);
  drawCircle(2);

  //seconds
  draw_seconds();
  draw_minutes();
  draw_hours();

}


//---------------------------------背景---------------------------------//
//レンガは1ブロックが画面サイズを縦24,横12(定義:divAmount)で割った大きさにする
const drawBackGround = () => {

  p5obj.stroke(64, 18, 20, 20);

  brickSize[0] = xsize / divAmount[0];
  brickSize[1] = ysize / divAmount[1];

  for (i = 0; i< divAmount[0]; i++) {

    for (k=0; k< divAmount[1]; k++) {
      if (k % 2 == 1) {
        p5obj.rect(i * brickSize[0] + brickSize[0]/2, k * brickSize[1], brickSize[0], brickSize[1]);
      } else {
        p5obj.rect(i * brickSize[0], k * brickSize[1], brickSize[0], brickSize[1]);
      }
    }
  }
}


//---------------------------------秒数を連続的に変換---------------------------------//
const getTimes = () => {
  // 描画切り替わったときにsecondを初期化
  currentSec = p5obj.second();
  if (currentSec != formerSec) {
    second = formerSec = currentSec;
  }
  
  //secondをframeRateごとに増加させる→1/n秒変数
  second += 1/p5obj.frameRate;
  minute = p5obj.minute() + second / 60;
  hour = p5obj.hour() % 12 + minute / 60;

  //console.log( second + "\n");
}

//---------------------------------円の描画---------------------------------//
const drawCircle = (arg: number) => {
  x = circleCenter[arg];
  y = ysize/2;
  //円
  p5obj.fill(173, 157, 148, 100);
  p5obj.circle(x, y, circleRadius*2);

  p5obj.noFill();
  p5obj.stroke(0, 0, 0);
  p5obj.strokeWeight(0.75);
  p5obj.circle(x, y, circleRadius*2);

  //五芒星
  p5obj.stroke(255, 255, 255, 70);
  p5obj.strokeWeight(2);
  r = circleRadius - 5;
  p5obj.beginShape();
  for (i = 0; i < 5; i++) {
    p5obj.vertex(x + r*p5obj.cos(4 * p5obj.PI * i/5 - p5obj.PI/2), y + r*p5obj.sin(4 * p5obj.PI * i/5  - p5obj.PI/2));
  }
  p5obj.endShape(p5obj.CLOSE);

  //時計の各パーツの表示
  p5obj.textAlign(p5obj.CENTER);
  switch(arg) {
  case 0:
    t = "Hours";
    break;
  case 1:
    t = "Minutes";
    break;
  case 2:
    t = "Seconds";
    break;
  }
  p5obj.textSize(20);
  p5obj.fill(255, 255, 255);
  p5obj.text(t, x, y - circleRadius * 1.3);


  //数字の描画
  for (i = 0; i < 12; i++) {
    r = circleRadius * 1.1;
    angle = p5obj.radians(30 * i - 90);
    goal[0] = x + (r * p5obj.cos(angle));
    goal[1] = y + (r * p5obj.sin(angle)) + 4;

    switch(i) {
    case 1:
      t = "I";
      break;
    case 2:
      t = "II";
      break;
    case 3:
      t = "III";
      break;
    case 4:
      t = "IV";
      break;
    case 5:
      t = "V";
      break;
    case 6:
      t = "VI";
      break;
    case 7:
      t = "VII";
      break;
    case 8:
      t = "VIII";
      break;
    case 9:
      t = "IX";
      break;
    case 10:
      t = "X";
      break;
    case 11:
      t = "XI";
      break;
    case 0:
      t = "XII";
      break;
    }
    p5obj.textSize(15);
    p5obj.text(t, goal[0], goal[1]);
  }

  p5obj.noStroke();
  p5obj.fill(95, 194, 103, 250);
  p5obj.circle(xsize*0.412, ysize/5*4.305, 10);
  p5obj.fill(207, 193, 87, 250);
  p5obj.circle(xsize*0.412, ysize/5*4.455, 10);
  p5obj.fill(209, 61, 66, 250);
  p5obj.circle(xsize*0.412, ysize/5*4.6, 10);
  p5obj.fill(0, 0, 0, 50);
  p5obj.circle(xsize*0.557, ysize/5*4.455, 10);
  p5obj.fill(255, 255, 255, 150);
  p5obj.text("時刻の読み方→ \" (　 の数 - 1 )×12  +  (　 の数 - 1 ) \" 時 / 分 / 秒", xsize/2, ysize/5*4.5);
}



//軽量化はダルいのでやりません
//---------------------------------秒数の描画---------------------------------//
const draw_seconds = () => {

  //---------針の描画---------//
  //周期12
  x = circleCenter[2];
  y = ysize/2;
  r = circleRadius;
  angle = p5obj.radians(30 * (p5obj.second() % 12) - 90);
  goal[0] = x + (r * p5obj.cos(angle));
  goal[1] = y + (r * p5obj.sin(angle));

  p5obj.stroke(0, 0, 0);
  p5obj.strokeWeight(1);
  p5obj.line(x, y, goal[0], goal[1]);

  //周期5
  r = circleRadius/3*2;
  angle = p5obj.radians(6 * second - 90);
  goal[0] = x + (r * p5obj.cos(angle));
  goal[1] = y + (r * p5obj.sin(angle));

  p5obj.stroke(100, 50, 50);
  p5obj.strokeWeight(1);
  p5obj.line(x, y, goal[0], goal[1]);

  //---------円点の描画---------//
  //周期12
  r = circleRadius * 0.9;
  p5obj.noStroke();
  p5obj.fill(0, 0, 0, 50);

  for (i = 0; i < (p5obj.second() % 12 + 1); i++) {
    angle = p5obj.radians(30 * i - 90);
    goal[0] = x + (r * p5obj.cos(angle));
    goal[1] = y + (r * p5obj.sin(angle));

    p5obj.circle(goal[0], goal[1], 10);
  }
  p5obj.noFill();

  //周期5
  r = circleRadius*0.6;
  p5obj.noStroke();
  p5obj.fill(95, 194, 103, 250);

  for (i = 0; i < (p5obj.floor(p5obj.second() / 12) + 1); i++) {
    angle = p5obj.radians(72 * i - 90);
    goal[0] = x + (r * p5obj.cos(angle));
    goal[1] = y + (r * p5obj.sin(angle));

    p5obj.circle(goal[0], goal[1], 15);
  }
  p5obj.noFill();

  //---------背景の描画---------//
  r = circleRadius*2;
  p5obj.fill(112,245,77, 40);
  p5obj.noStroke();

  param = p5obj.asin(1 - second / 30);
  //console.log(param + "\n");

  p5obj.arc(x, y, r, r, param, p5obj.PIE-param + 0.13, p5obj.CHORD); //目視で0.13足して水平に修正しました 理由が謎です すみません...
  p5obj.noFill();
}




//---------------------------------分数の描画---------------------------------//
const draw_minutes = () => {

  //---------針の描画---------//
  //周期12
  x = circleCenter[1];
  y = ysize/2;
  r = circleRadius;
  angle = p5obj.radians(30 * (p5obj.minute() % 12) - 90);
  goal[0] = x + (r * p5obj.cos(angle));
  goal[1] = y + (r * p5obj.sin(angle));

  p5obj.stroke(0, 0, 0);
  p5obj.strokeWeight(1);
  p5obj.line(x, y, goal[0], goal[1]);

  //周期5
  r = circleRadius/3*2;
  n = (p5obj.floor(p5obj.minute() / 12));
  angle = p5obj.radians(minute - 90);
  goal[0] = x + (r * p5obj.cos(angle));
  goal[1] = y + (r * p5obj.sin(angle));

  p5obj.stroke(100, 50, 50);
  p5obj.strokeWeight(1);
  p5obj.line(x, y, goal[0], goal[1]);

  //---------円点の描画---------//
  //周期12
  r = circleRadius * 0.9;
  p5obj.noStroke();
  p5obj.fill(0, 0, 0, 50);

  for (i = 0; i < (p5obj.minute() % 12 + 1); i++) {
    angle = p5obj.radians(30 * i - 90);
    goal[0] = x + (r * p5obj.cos(angle));
    goal[1] = y + (r * p5obj.sin(angle));

    p5obj.circle(goal[0], goal[1], 10);
  }
  p5obj.noFill();

  //周期5
  r = circleRadius*0.6;
  p5obj.noStroke();
  p5obj.fill(207, 193, 87, 250);

  for (i = 0; i < (p5obj.floor(p5obj.minute() / 12) + 1); i++) {
    angle = p5obj.radians(72 * i - 90);
    goal[0] = x + (r * p5obj.cos(angle));
    goal[1] = y + (r * p5obj.sin(angle));

    p5obj.circle(goal[0], goal[1], 15);
  }
  p5obj.noFill();

  //---------背景の描画---------//
  r = circleRadius*2;
  p5obj.fill(212, 209, 59, 40);
  p5obj.noStroke();

  param = p5obj.asin(1 - minute / 30);

  p5obj.arc(x, y, r, r, param, p5obj.PIE-param + 0.13, p5obj.CHORD);
  p5obj.noFill();
}

//---------------------------------時数の描画---------------------------------//
const draw_hours = () => {

  //---------針の描画---------//
  //周期12
  x = circleCenter[0];
  y = ysize/2;
  r = circleRadius;
  angle = p5obj.radians(30 * (p5obj.hour() % 12) - 90);
  goal[0] = x + (r * p5obj.cos(angle));
  goal[1] = y + (r * p5obj.sin(angle));

  p5obj.stroke(0, 0, 0);
  p5obj.strokeWeight(1);
  p5obj.line(x, y, goal[0], goal[1]);

  //周期2
  r = circleRadius/3*2;
  n = p5obj.floor(p5obj.hour() / 12);
  angle = p5obj.radians(15 * hour - 90);
  goal[0] = x + (r * p5obj.cos(angle));
  goal[1] = y + (r * p5obj.sin(angle));

  p5obj.stroke(100, 50, 50);
  p5obj.strokeWeight(1);
  p5obj.line(x, y, goal[0], goal[1]);

  //---------円点の描画---------//
  //周期12
  r = circleRadius * 0.9;
  p5obj.noStroke();
  p5obj.fill(0, 0, 0, 50);

  for (i = 0; i < (p5obj.hour() % 12 + 1); i++) {
    angle = p5obj.radians(30 * i - 90);
    goal[0] = x + (r * p5obj.cos(angle));
    goal[1] = y + (r * p5obj.sin(angle));

    p5obj.circle(goal[0], goal[1], 10);
  }
  p5obj.noFill();

  //周期2
  r = circleRadius*0.6;
  p5obj.noStroke();
  p5obj.fill(209, 61, 66, 250);

  for (i = 0; i < (p5obj.floor(p5obj.hour() / 6) + 1); i++) {
    angle = p5obj.radians(180 * i - 90);
    goal[0] = x + (r * p5obj.cos(angle));
    goal[1] = y + (r * p5obj.sin(angle));

    p5obj.circle(goal[0], goal[1], 15);
  }
  p5obj.noFill();

  //---------背景の描画---------//
  r = circleRadius*2;
  p5obj.fill(209, 61, 66, 20);
  p5obj.noStroke();

  param = p5obj.asin(1 - hour / 12);

  p5obj.arc(x, y, r, r, param, p5obj.PIE-param + 0.13, p5obj.CHORD);
  p5obj.noFill();
}

};

export default sketch;
